    getTimeClass: function getTimeClass(type) {
      if (type == 'type_gjdjfb' || type == 'type_wqrgj' || type == 'type_yhlgj') {
        //告警级别分布
        return 'd_time1';
      } else if (type == 'type_gjlxfb' || type == 'type_gjcsfb' || type == 'type_yqrdczgj') {
        //告警类型分布
        return 'd_time2';
      }
      return '';
    },
    getFormatDay: function getFormatDay(value) {
      if (value) {
        var arrs = value.split('-');
        if (arrs && arrs.length == 3) {
          return "".concat(arrs[1], " / ").concat(arrs[2]);
        } else {
          return value;
        }
      }
      return '';
    },
